import json, sys
posts = []
for line in sys.stdin.buffer:
    try:
        d = json.loads(line.decode('utf-8'))
        posts.append((d.get('title','') or ''))
    except: pass
# Categorize
categories = {}
for t in posts:
    tl = t.lower()
    if any(w in tl for w in ['buffett','rockfeller','munger','bezos','cuban','gates','musk','rohn','carnegie','soros']):
        cat = 'BILLIONAIRE_QUOTES'
    elif any(w in tl for w in ['inamori','kazuo','do thai','trung hoa','nhat ban','han quoc']):
        cat = 'CULTURAL_WISDOM'  
    elif any(w in tl for w in ['tai san','dong tien','dau tu','co phieu','bat dong san','loi nhuan','tài sản','đầu tư','dòng tiền','bất động sản']):
        cat = 'ASSET_CASHFLOW'
    elif any(w in tl for w in ['tu duy','thoi quen','thanh cong','tư duy','thói quen','thành công']):
        cat = 'MINDSET'
    elif any(w in tl for w in ['tiet kiem','chi tieu','tiết kiệm','chi tiêu','tai chinh','tài chính']):
        cat = 'PERSONAL_FINANCE'
    else:
        cat = 'OTHER'
    categories[cat] = categories.get(cat, 0) + 1

for cat, count in sorted(categories.items(), key=lambda x: -x[1]):
    sys.stdout.buffer.write(f'{cat}: {count}\n'.encode('utf-8'))
sys.stdout.buffer.write(f'\nTotal: {len(posts)}\n'.encode('utf-8'))
